public class Song {
    private String title;
    private String artist;
    private int energyLevel;

    public Song(String title, String artist, int energyLevel) {
        this.title = title;
        this.artist = artist;
        this.energyLevel = energyLevel;
    }

    public String getTitle() {
        return title;
    }

    public String getArtist() {
        return artist;
    }

    public int getEnergyLevel() {
        return energyLevel;
    }

    @Override
    public String toString() {
        return title + " by " + artist + " (energy " + energyLevel + ")";
    }
}
